solve:{[tokens;codes]
  norm:{[x] t:(lower x);
    (t="1")|t="t"|t="true"};
  longs:();floats:();bools:();chars:();syms:();symidx:();
  effective:"";recast:0;total:0;i:0;
  while[i<count tokens;
    t:tokens i;c:`$codes i;done:0;
    if[not done;
      v:"J"$t;
      if[((-127<=v)&(v<=127))&((count t)>=1)&all ((first t) in "0123456789-");
        longs,:v;effective,:enlist "j";total+:v;done:1];
      if[not done;
        v:"F"$t;
        if[((-127<=v)&(v<=127));
          floats,:v;effective,:enlist "f";total+:v;done:1]];
      if[not done;
        v:$[norm t;1;0];
        bools,:v;effective,:enlist "b";total+:v;done:1]];
    if[not done;
      if[count t=1;
        chars,:enlist .Q.A?t;effective,:enlist "c";total+:.Q.A?t;done:1]];
    if[not done;
      ix:0;
      while[(ix<count syms)&not syms[ix]~t;ix+:1];
      if[ix=count syms;syms,:enlist t];
      symidx,:ix;effective,:enlist "s";total+:ix;done:1];
    if[not (c=`$first effective)~c;recast+:1];
