         if[(-1 s?)";";s:s (til (1+first (where ";"~s)) mod count s)];
         if[(-1 s?)",";s:s (til (1+first (where ","~s)) mod count s)];
         if[(-1 s?)("e"~lower last s);s:s (til (count s)-1)];
         if[(-1 s?)("E"~last s);s:s (til (count s)-1)];
         if[(s~"");s:"0"];
         if[((count s)&first s="-");s:"0"],
         if["j"~type s;"j"~type s];
         if["I"~type s;"j"~type s];
