   ix:where `j=`$(effective "j");
   `effective`longs`floats`bools`chars`syms`symIdx`recast`total!(effective;longs;floats;bools;chars;syms;symidx;recast;sum longs+floats+bools+chars+symidx)};

clean:{[x]
   if[2=count x;if[(first x)="-";if[(last x)=".";x:enlist "."]];
   if[2=count x;if[(first x)="-";if[(last x)=".";x:enlist "."]]];x};

validint:{[x]
   x:clean x;
   if[1=count x;if[(first x)="-";0b]];
   if[1=count x;if[(first x)=".";0b]];
   if[(first x)="-";x:1 _ x];
   if[all x in "0123456789";if[0=count x;0b];v:"J"$x;(abs v)<1000000000b];
   if[not all x in "0123456789";0b];1b};

validfloat:{[x]
   x:clean x;
   if[1=count x;if[(first x)="-";0b]];
   if[1=count x;if[(first x)=".";0b]];
   if[(first x)="-";x:1 _ x];
   if[not all x in ".0123456789";0b];
   if[(count x)=1;0b];
   parts:"." vs x;
   if[1=count parts;0b];
   if[2=count parts;if[(0=count first parts)&(0=count last parts);0b];
     if[(0=count first parts)&(0=count last parts);0b]];
   if[not ((0=count first parts)|(0=count last parts));if[not ((count first parts)&count last parts);0b]];
   v:"F"$x;(abs v)<1000000b};
